// Bundles the dependency-free export player (src/lib/plays/export/player-runtime.ts, which pulls in
// the real geometry/playback/resolve/bounds/frames math by relative import) into one IIFE, and
// base64-embeds the team logo — both written out as plain TS string constants, not public/ static
// files or a runtime fs.readFile. A runtime readFile(path.join(process.cwd(), ...)) call was tried
// first and made Turbopack's build-time asset tracer try to statically resolve a directory reference
// from that dynamic path, which walked into an unrelated broken symlink under training/work/ and
// panicked the whole build — a plain module import has no such tracing step at all.
import { build } from "esbuild";
import { readFile, writeFile, mkdir } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(here, "..");
const entry = path.join(root, "src/lib/plays/export/player-runtime.ts");
const logoFile = path.join(root, "public/brand/evangel-lightning-bolt.png");
const outDir = path.join(root, "src/lib/plays/export/generated");
const outFile = path.join(outDir, "player-bundle.ts");

async function run() {
  const result = await build({
    entryPoints: [entry],
    bundle: true,
    write: false,
    format: "iife",
    target: "es2019",
    minify: true,
    logLevel: "warning",
  });
  const js = result.outputFiles[0].text;
  const logoBuf = await readFile(logoFile);
  const logoDataUri = `data:image/png;base64,${logoBuf.toString("base64")}`;

  await mkdir(outDir, { recursive: true });
  const content =
    `// GENERATED by scripts/build-playbook-export-bundle.mjs — do not edit by hand.\n` +
    `// Source: src/lib/plays/export/player-runtime.ts (and everything it imports), plus\n` +
    `// public/brand/evangel-lightning-bolt.png, base64-embedded.\n` +
    `// Regenerate with: node scripts/build-playbook-export-bundle.mjs\n` +
    `export const PLAYER_BUNDLE_JS = ${JSON.stringify(js)};\n` +
    `export const LOGO_DATA_URI = ${JSON.stringify(logoDataUri)};\n`;
  await writeFile(outFile, content, "utf8");
  console.log(`Wrote ${path.relative(root, outFile)} (${(js.length / 1024).toFixed(1)} KB JS + ${(logoDataUri.length / 1024).toFixed(1)} KB logo)`);
}

run().catch((err) => {
  console.error(err);
  process.exit(1);
});
